import{_ as s,o,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Rebuilding a Faster OSD with Future - Kefu Chai & Radoslaw Zarzynski, Red Hat","description":"","frontmatter":{"title":"Rebuilding a Faster OSD with Future - Kefu Chai & Radoslaw Zarzynski, Red Hat","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Crimson 项目","SSD","I/O 性能","用户空间驱动器"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Rebuilding_a_Faster_OSD_with_Future_-_Kefu_Chai_Radoslaw_Zarzynski_Red_Hat.md","filePath":"posts/2019/Rebuilding_a_Faster_OSD_with_Future_-_Kefu_Chai_Radoslaw_Zarzynski_Red_Hat.md","lastUpdated":1780459816000}'),l={name:"posts/2019/Rebuilding_a_Faster_OSD_with_Future_-_Kefu_Chai_Radoslaw_Zarzynski_Red_Hat.md"};function n(e,t,a,_,g,p){return o(),r("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph Crimson 项目进展及未来方向</p><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议内容</strong>：</p><p><strong>一、会议背景</strong></p><ol><li><strong>技术发展</strong>： 随着固态硬盘（SSD）和NVMe接口的普及，存储速度得到了显著提升。然而，Ceph存储系统在处理高速存储设备时，面临着性能瓶颈。</li><li><strong>CSD架构</strong>： Ceph存储驱动器（CSD）最初针对旋转硬盘设计，其I/O性能有限。随着存储设备的升级，CSD的性能已无法满足需求。</li></ol><p><strong>二、Crimson项目</strong></p><ol><li><strong>项目目标</strong>： 重构CSD，使其能够充分利用高速存储设备，提高I/O性能。</li><li><strong>技术方案</strong>： <ul><li>使用用户空间驱动器，减少内核空间与用户空间之间的数据拷贝。</li><li>采用无锁设计，避免锁竞争导致的性能瓶颈。</li><li>利用未来存储设备（如NVMe）的并行处理能力。</li></ul></li><li><strong>项目进展</strong>： <ul><li>已完成CSD的重构，初步测试结果表明性能提升显著。</li><li>目前仅支持内存存储和简单的I/O路径，未来将支持更多功能。</li></ul></li></ol><p><strong>三、下一步工作</strong></p><ol><li><strong>性能测试</strong>： 将性能测试集成到持续集成（CI）流程中，确保代码质量。</li><li><strong>功能完善</strong>： 支持更多存储设备、恢复机制和高级功能。</li><li><strong>社区合作</strong>： 欢迎更多开发者参与Crimson项目，共同推动Ceph存储系统的发展。</li></ol><p><strong>四、讨论要点</strong></p><ol><li><strong>RocksDB的集成</strong>： <ul><li>短期内，Crimson将支持RocksDB，通过用户空间线程或扩展RocksDB来实现。</li><li>长期来看，可能不再使用RocksDB，而是利用新型存储硬件。</li></ul></li><li><strong>网络栈</strong>： 目前使用基于内核的网络栈，未来可能考虑使用PDK网络栈。</li></ol><p><strong>五、行动计划</strong></p><ol><li><strong>性能测试</strong>： 在CI流程中集成性能测试。</li><li><strong>功能开发</strong>： 优先开发支持更多存储设备和恢复机制的功能。</li><li><strong>社区建设</strong>： 持续开展社区活动，吸引更多开发者参与。</li></ol><p><strong>六、总结</strong></p><p>Crimson项目旨在重构Ceph存储驱动器，提高其性能。项目进展顺利，未来将支持更多功能和存储设备。Ceph社区将共同努力，推动Ceph存储系统的发展。</p>',17)])])}const C=s(l,[["render",n]]);export{d as __pageData,C as default};
